import { useState } from 'react'
import { Questionnaire, type QuestionnaireAnswers } from 'moru-ui'

export function ProjectQuestionnaire() {
  const [answers, setAnswers] = useState<QuestionnaireAnswers | null>(null)
  return (
    <div>
      <Questionnaire
        aria-label="Project preferences"
        onComplete={setAnswers}
        questions={[
          { id: 'name', title: 'What is your project called?', type: 'text', required: true },
          {
            id: 'team',
            title: 'Who will use it?',
            type: 'single',
            required: true,
            options: [
              { value: 'personal', label: 'Only me' },
              { value: 'team', label: 'My team' },
            ],
          },
        ]}
      />
      {answers && <pre aria-label="Your answers">{JSON.stringify(answers, null, 2)}</pre>}
    </div>
  )
}
